    'Kellgren-Lawrence radiographic osteoarthritis grade of the medial compartment, 0 to 4.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.kellgren_lawrence_grade_lateral IS
    'Kellgren-Lawrence radiographic osteoarthritis grade of the lateral compartment, 0 to 4.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.kellgren_lawrence_grade_patellofemoral IS
    'Kellgren-Lawrence radiographic osteoarthritis grade of the patellofemoral compartment, 0 to 4.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.mri_performed IS
    'Whether an MRI scan has been performed.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.mri_findings IS
    'Free-text summary of MRI findings.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.ct_performed IS
    'Whether a CT scan has been performed.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.ct_indication IS
    'Indication for the CT scan: robotic-assisted surgical planning, bone-loss assessment, or other.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.physiotherapy_tried IS
    'Whether physiotherapy has been tried as a conservative measure.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.physiotherapy_duration_weeks IS
    'Duration of physiotherapy in weeks.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.weight_management_advice_given IS
    'Whether weight-management advice has been given as a conservative measure.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.injection_given IS
    'Whether an intra-articular injection (corticosteroid or hyaluronic acid) has been given.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.injection_type IS
    'Type of intra-articular injection given: corticosteroid, hyaluronic acid, both, or other.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.injection_count IS
    'Number of intra-articular injections given.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.injection_response IS
    'Response to the intra-articular injection: good, partial, or none.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.nsaid_analgesic_trial IS
    'Whether an NSAID or analgesic trial has been undertaken as a conservative measure.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.nsaid_analgesic_response IS
    'Response to the NSAID or analgesic trial: good, partial, or none.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.walking_aid_trial IS
    'Whether a walking-aid trial has been undertaken as a conservative measure.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.conservative_measures_exhausted IS
    'Whether all appropriate conservative measures have been exhausted. Drives the computed-candidacy recommendation and the conservative-treatment-not-exhausted safety flag.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.diabetes_controlled IS
    'Diabetes control status: not diabetic, well controlled, or poorly controlled.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.cardiac_disease IS
    'Whether cardiac disease is present.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.bleeding_disorder_or_anticoagulant IS
    'Whether a bleeding disorder is present or the patient is taking an anticoagulant.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.smoking_status IS
    'Smoking status: never, ex-smoker, or current.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.general_fitness_note IS
    'Free-text general-fitness note. This is a high-level screen only; it does not grade ASA physical status, which belongs to the ASA-grading pre-operative sibling forms.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.fbc_done IS
    'Whether a full blood count (FBC) has been done.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.renal_function_done IS
    'Whether renal function tests have been done.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.clotting_done IS
    'Whether clotting or INR tests have been done.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.ecg_done IS
    'Whether an electrocardiogram (ECG) has been done.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.mrsa_screen_done IS
    'Whether an MRSA screen has been done.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.urinalysis_done IS
    'Whether urinalysis has been done.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.risks_benefits_discussed IS
    'Whether the risks and benefits of surgery have been discussed with the patient.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.realistic_expectations_discussed IS
    'Whether realistic expectations of surgical outcome have been discussed with the patient.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.patient_decision_aid_given IS
    'Whether a patient decision aid has been given.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.interpreter_required IS
    'Whether an interpreter was required for the shared decision-making discussion.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.plan_recommendation IS
    'Clinician recommendation: total knee replacement, partial knee replacement, continue conservative management, MDT review, or not currently a candidate.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.target_list_date IS
    'Target date to add the patient to the surgical waiting list, if applicable.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation.responsible_surgeon IS
    'Name of the surgeon responsible for the operation, if a surgical recommendation is made.';

CREATE INDEX knee_replacement_surgery_evaluation_patient_id_index
    ON knee_replacement_surgery_evaluation (patient_id);

CREATE INDEX knee_replacement_surgery_evaluation_clinician_id_index
    ON knee_replacement_surgery_evaluation (clinician_id);

-- ========================================================================
-- END 04_create_table_knee_replacement_surgery_evaluation.sql
-- ========================================================================

-- ========================================================================
-- BEGIN 05_create_table_knee_replacement_surgery_evaluation_grade.sql
-- ========================================================================

-- Computed and signed-off grading result for one knee replacement surgery
-- evaluation. Stores both the engine-computed values and the clinician-final
-- values with an override reason, so the override is auditable rather than
-- silent.

CREATE TABLE knee_replacement_surgery_evaluation_grade (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,
    knee_replacement_surgery_evaluation_id UUID NOT NULL UNIQUE
        REFERENCES knee_replacement_surgery_evaluation(id) ON DELETE CASCADE,

    oks_total INTEGER
        CHECK (oks_total IS NULL OR oks_total BETWEEN 0 AND 48),
    computed_oks_category VARCHAR(20) NOT NULL DEFAULT ''
        CHECK (computed_oks_category IN ('severe', 'moderate', 'mild-to-moderate', 'satisfactory', '')),
    final_oks_category VARCHAR(20) NOT NULL DEFAULT ''
        CHECK (final_oks_category IN ('severe', 'moderate', 'mild-to-moderate', 'satisfactory', '')),

    max_kellgren_lawrence_grade SMALLINT
        CHECK (max_kellgren_lawrence_grade IS NULL OR max_kellgren_lawrence_grade BETWEEN 0 AND 4),

    computed_candidacy VARCHAR(25) NOT NULL DEFAULT ''
        CHECK (computed_candidacy IN ('strong-candidate', 'candidate', 'continue-conservative', 'not-indicated', 'mdt-review', '')),
    final_candidacy VARCHAR(25) NOT NULL DEFAULT ''
        CHECK (final_candidacy IN ('strong-candidate', 'candidate', 'continue-conservative', 'not-indicated', 'mdt-review', '')),
    override_reason VARCHAR(500) NOT NULL DEFAULT '',

    clinician_notes TEXT NOT NULL DEFAULT '',
    signed_by_name VARCHAR(255) NOT NULL DEFAULT '',
    signed_at TIMESTAMPTZ,
    graded_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TRIGGER trigger_knee_replacement_surgery_evaluation_grade_updated_at
    BEFORE UPDATE ON knee_replacement_surgery_evaluation_grade
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE knee_replacement_surgery_evaluation_grade IS
    'Computed and signed-off grading result for one knee replacement surgery evaluation. Stores both the engine-computed values and the clinician-final values with an override reason.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade.created_at IS
    'Timestamp when this row was created.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade.knee_replacement_surgery_evaluation_id IS
    'Foreign key to the knee_replacement_surgery_evaluation table, unique because grading is one-to-one with the evaluation.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade.oks_total IS
    'Oxford Knee Score total, 0 to 48, being the sum of the twelve item scores. 48 is the best possible outcome.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade.computed_oks_category IS
    'Oxford Knee Score category computed by the engine: severe (0-19), moderate (20-29), mild-to-moderate (30-39), or satisfactory (40-48).';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade.final_oks_category IS
    'Oxford Knee Score category signed off by the clinician, which may equal or differ from the computed value.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade.max_kellgren_lawrence_grade IS
    'Highest Kellgren-Lawrence radiographic grade across the medial, lateral, and patellofemoral compartments, 0 to 4.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade.computed_candidacy IS
    'Surgical candidacy recommendation computed by the engine: strong-candidate, candidate, continue-conservative, not-indicated, or mdt-review.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade.final_candidacy IS
    'Surgical candidacy recommendation signed off by the clinician, which may equal or differ from the computed value.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade.override_reason IS
    'Reason the clinician set a final candidacy differently from the computed value, mandatory when they differ.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade.clinician_notes IS
    'Free-text clinician summary notes.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade.signed_by_name IS
    'Name of the clinician who signed the evaluation.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade.signed_at IS
    'Timestamp of the clinician electronic signature.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade.graded_at IS
    'Timestamp when the engine last computed the result.';

-- ========================================================================
-- END 05_create_table_knee_replacement_surgery_evaluation_grade.sql
-- ========================================================================

-- ========================================================================
-- BEGIN 06_create_table_knee_replacement_surgery_evaluation_grade_flag.sql
-- ========================================================================

-- Safety-critical flags that fire independently of the OKS score and the
-- clinician's candidacy override, with a priority and a suggested action for
-- the joint-replacement multidisciplinary team. Flags are never suppressed.

CREATE TABLE knee_replacement_surgery_evaluation_grade_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,
    knee_replacement_surgery_evaluation_grade_id UUID NOT NULL
        REFERENCES knee_replacement_surgery_evaluation_grade(id) ON DELETE CASCADE,
    flag_id VARCHAR(50) NOT NULL,
    category VARCHAR(40) NOT NULL DEFAULT ''
        CHECK (category IN (
            'conservative-treatment-not-exhausted',
            'high-bmi-surgical-risk',
            'pre-op-bloods-incomplete',
            'fixed-flexion-deformity',
            'bilateral-symptomatic',
            'paediatric',
            'other',
            ''
        )),
    priority VARCHAR(10) NOT NULL DEFAULT ''
        CHECK (priority IN ('low', 'medium', 'high', '')),
    description VARCHAR(500) NOT NULL DEFAULT '',
    suggested_action VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX knee_replacement_surgery_evaluation_grade_flag_grade_id_index
    ON knee_replacement_surgery_evaluation_grade_flag (knee_replacement_surgery_evaluation_grade_id);

CREATE TRIGGER trigger_knee_replacement_surgery_evaluation_grade_flag_updated_at
    BEFORE UPDATE ON knee_replacement_surgery_evaluation_grade_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE knee_replacement_surgery_evaluation_grade_flag IS
    'Safety-critical flags that fire independently of the OKS score and the clinician candidacy override, with a priority and a suggested action for the joint-replacement multidisciplinary team.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade_flag.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade_flag.created_at IS
    'Timestamp when this row was created.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade_flag.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade_flag.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade_flag.knee_replacement_surgery_evaluation_grade_id IS
    'Foreign key to the parent knee_replacement_surgery_evaluation_grade table.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade_flag.flag_id IS
    'Stable flag identifier, such as F-FIXED-FLEXION-DEFORMITY-001.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade_flag.category IS
    'Flag category, such as conservative-treatment-not-exhausted or high-bmi-surgical-risk.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade_flag.priority IS
    'Priority: low, medium, or high.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade_flag.description IS
    'Human-readable description of what fired the flag.';
COMMENT ON COLUMN knee_replacement_surgery_evaluation_grade_flag.suggested_action IS
    'Suggested clinical action, such as "complete the pre-operative bloods checklist before listing for surgery".';

-- ========================================================================
-- END 06_create_table_knee_replacement_surgery_evaluation_grade_flag.sql
-- ========================================================================
